19	/**
20	 * Finds all npm dependencies and their expected versions for a given project.
21	 */
22	export function findNpmDependencies(
23	  workspaceRoot: string,
24	  sourceProject: ProjectGraphProjectNode,
25	  projectGraph: ProjectGraph,
26	  projectFileMap: ProjectFileMap,
27	  buildTarget: string,
28	  options: {
29	    includeTransitiveDependencies?: boolean;
30	    ignoredFiles?: string[];
31	    useLocalPathsForWorkspaceDependencies?: boolean;
32	    runtimeHelpers?: string[];
33	  } = {}
34	): Record<string, string> {
35	  let seen: null | Set<string> = null;
36	  if (options.includeTransitiveDependencies) {
37	    seen = new Set<string>();
38	  }
39	
40	  const results: Record<string, string> = {};
41	
42	  function collectAll(
43	    currentProject: ProjectGraphProjectNode,
44	    collectedDeps: Record<string, string>
45	  ): void {
46	    if (seen?.has(currentProject.name)) return;
47	    seen?.add(currentProject.name);
48	
49	    collectDependenciesFromFileMap(
50	      workspaceRoot,
51	      currentProject,
52	      projectGraph,
53	      projectFileMap,
54	      buildTarget,
55	      options.ignoredFiles,
56	      options.useLocalPathsForWorkspaceDependencies,
57	      collectedDeps
58	    );
59	
60	    collectHelperDependencies(
61	      workspaceRoot,
62	      currentProject,
63	      projectGraph,
64	      buildTarget,
65	      options.runtimeHelpers,
66	      collectedDeps
67	    );
68	
69	    if (options.includeTransitiveDependencies) {
70	      const projectDeps = projectGraph.dependencies[currentProject.name];
71	      for (const dep of projectDeps) {
72	        const projectDep = projectGraph.nodes[dep.target];
73	        if (projectDep) collectAll(projectDep, collectedDeps);
74	      }
75	    }
76	  }
77	
78	  collectAll(sourceProject, results);
79	
80	  return results;
81	}
