86	function collectDependenciesFromFileMap(
87	  workspaceRoot: string,
88	  sourceProject: ProjectGraphProjectNode,
89	  projectGraph: ProjectGraph,
90	  projectFileMap: ProjectFileMap,
91	  buildTarget: string,
92	  ignoredFiles: string[],
93	  useLocalPathsForWorkspaceDependencies: boolean,
94	  npmDeps: Record<string, string>
95	): void {
96	  const rawFiles = projectFileMap[sourceProject.name];
97	  if (!rawFiles) return;
98	
99	  // If build target does not exist in project, use all files as input.
100	  // This is needed for transitive dependencies for apps -- where libs may not be buildable.
101	  const inputs = sourceProject.data.targets[buildTarget]
102	    ? getTargetInputs(readNxJson(), sourceProject, buildTarget).selfInputs
103	    : ['{projectRoot}/**/*'];
104	  if (ignoredFiles) {
105	    for (const pattern of ignoredFiles) {
106	      inputs.push(`!${pattern}`);
107	    }
108	  }
109	  const files = filterUsingGlobPatterns(
110	    sourceProject.data.root,
111	    projectFileMap[sourceProject.name] || [],
112	    inputs
113	  );
114	
115	  for (const fileData of files) {
116	    if (
117	      !fileData.deps ||
118	      fileData.file ===
119	        joinPathFragments(sourceProject.data.root, 'package.json')
120	    ) {
121	      continue;
122	    }
123	
124	    for (const dep of fileData.deps) {
125	      const target = fileDataDepTarget(dep);
126	
127	      // If the node is external, then read package info from `data`.
128	      const externalDep = projectGraph.externalNodes[target];
129	      if (externalDep?.type === 'npm') {
130	        npmDeps[externalDep.data.packageName] = externalDep.data.version;
131	        continue;
132	      }
133	
134	      // If node is internal, then try reading package info from `package.json` (which must exist for this to work).
135	      const workspaceDep = projectGraph.nodes[target];
136	      if (!workspaceDep) continue;
137	      const cached = seenWorkspaceDeps[workspaceDep.name];
138	      if (cached) {
139	        npmDeps[cached.name] = cached.version;
140	      } else {
141	        const packageJson = readPackageJson(workspaceDep, workspaceRoot);
