148	          let version: string;
149	          if (useLocalPathsForWorkspaceDependencies) {
150	            // Find the relative `file:...` path and use that as the version value.
151	            // This is useful for monorepos like Nx where the release will handle setting the correct version in dist.
152	            const depRoot = join(workspaceRoot, workspaceDep.data.root);
153	            const ownRoot = join(workspaceRoot, sourceProject.data.root);
154	            const relativePath = relative(ownRoot, depRoot);
155	            const filePath = normalizePath(relativePath); // normalize slashes for windows
156	            version = `file:${filePath}`;
157	          } else {
158	            // Otherwise, read the version from the dependencies `package.json` file.
159	            // This is useful for monorepos that commit release versions.
160	            // Users can also set version as "*" in source `package.json` files, which will be the value set here.
161	            // This is useful if they use custom scripts to update them in dist.
162	            version = packageJson.version ?? '*'; // fallback in case version is missing
163	          }
164	          npmDeps[packageJson.name] = version;
165	          seenWorkspaceDeps[workspaceDep.name] = {
166	            name: packageJson.name,
167	            version,
168	          };
169	        }
170	      }
171	    }
172	  }
173	}
