9	export function readTsConfig(
10	  tsConfigPath: string,
11	  sys?: ts.System
12	): ts.ParsedCommandLine {
13	  if (!tsModule) {
14	    tsModule = require('typescript');
15	  }
16	
17	  sys ??= tsModule.sys;
18	
19	  const readResult = tsModule.readConfigFile(tsConfigPath, sys.readFile);
20	  return tsModule.parseJsonConfigFileContent(
21	    readResult.config,
22	    sys,
23	    dirname(tsConfigPath)
24	  );
25	}
