27	export function readTsConfigFromTree(
28	  tree: Tree,
29	  tsConfigPath: string
30	): ts.ParsedCommandLine {
31	  if (!tsModule) {
32	    tsModule = ensureTypescript();
33	  }
34	
35	  const tsSysFromTree: ts.System = {
36	    ...tsModule.sys,
37	    readFile: (path) => tree.read(path, 'utf-8'),
38	  };
39	
40	  return readTsConfig(tsConfigPath, tsSysFromTree);
41	}
